  while (i < s.length) {
    let ch = s[i];
    if (inQuote) {
      if (ch === '\\') {
        i += 2;
        continue;
      }
      if (ch === '"') {
        inQuote = false;
      }
      i++;
      continue;
    }
    if (ch === '"') {
      inQuote = true;
      i++;
