function compareSemver(a, b) {
  const semverRegex = /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/;
  const matchA = a.match(semverRegex);
  const matchB = b.match(semverRegex);

  if (!matchA || !matchB) return null;

  const majorA = parseInt(matchA[1], 10);
  const minorA = parseInt(matchA[2], 10);
  const patchA = parseInt(matchA[3], 10);
  const preA = matchA[4] ? matchA[4].split('.') : [];

  const majorB = parseInt(matchB[1], 10);
  const minorB = parseInt(matchB[2], 10);
  const patchB = parseInt(matchB[3], 10);
  const preB = matchB[4] ? matchB[4].split('.') : [];

  if (majorA !== majorB) return majorA < majorB ? -1 : 1;
  if (minorA !== minorB) return minorA < minorB ? -1 : 1;
  if (patchA !== patchB) return patchA < patchB ? -1 : 1;

  if (preA.length === 0 && preB.length === 0) return 0;
  if (preA.length === 0) return 1;
  if (preB.length === 0) return -1;

  const maxLen = Math.max(preA.length, preB.length);
  for (let i = 0; i < maxLen; i++) {
    if (i >= preA.length) return -1;
    if (i >= preB.length) return 1;

    const idA = preA[i];
    const idB = preB[i];

    const isDigitA = /^\d+$/.test(idA);
    const isDigitB = /^\d+$/.test(idB);

    if (isDigitA && isDigitB) {
      const numA = parseInt(idA, 10);
      const numB = parseInt(idB, 10);
      if (numA !== numB) return numA < numB ? -1 : 1;
    } else if (isDigitA) {
      return -1;
    } else if (isDigitB) {
      return 1;
    } else {
      if (idA !== idB) return idA < idB ? -1 : 1;
    }
  }

  return 0;
}

function compareSemver(a, b) {
  function parse(version) {
    if (typeof version !== "string") return null;
    var match = /^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$/.exec(version);
    if (!match) return null;
    return {
      core: [match[1], match[2], match[3]],
      prerelease: match[4] === undefined ? null : match[4].split(".")
    };
  }

  function compareNumericStrings(a, b) {
    a = a.replace(/^0+(?=\d)/, "");
    b = b.replace(/^0+(?=\d)/, "");
    if (a.length !== b.length) return a.length < b.length ? -1 : 1;
    if (a === b) return 0;
    return a < b ? -1 : 1;
  }

  var va = parse(a);
