  if (!va || !vb) return null;

  for (var i = 0; i < 3; i++) {
    var coreComparison = compareNumericStrings(va.core[i], vb.core[i]);
    if (coreComparison !== 0) return coreComparison;
  }

  if (va.prerelease === null && vb.prerelease === null) return 0;
  if (va.prerelease === null) return 1;
  if (vb.prerelease === null) return -1;

  var length = Math.min(va.prerelease.length, vb.prerelease.length);
  for (var j = 0; j < length; j++) {
    var left = va.prerelease[j];
    var right = vb.prerelease[j];
    var leftNumeric = /^\d+$/.test(left);
    var rightNumeric = /^\d+$/.test(right);

    if (leftNumeric && rightNumeric) {
      var identifierComparison = compareNumericStrings(left, right);
      if (identifierComparison !== 0) return identifierComparison;
    } else if (leftNumeric !== rightNumeric) {
      return leftNumeric ? -1 : 1;
    } else if (left !== right) {
      return left < right ? -1 : 1;
