      const bit = available & -available;
      available -= bit;
      count += solve(
        columns | bit,
        ((diagonalsLeft | bit) << 1n) & all,
        (diagonalsRight | bit) >> 1n
      );
    }

    return count;
  }

  let total = 0n;
  const half = Math.floor(n / 2);

  for (let column = 0; column < half; column++) {
    const bit = 1n << BigInt(column);
    total += solve(
      bit,
      (bit << 1n) & all,
      bit >> 1n
    );
  }

  total *= 2n;

  if (n % 2 === 1) {
    const bit = 1n << BigInt(half);
