  const fractionPart = dot === -1 ? "" : value.slice(dot + 1);
  const keptFraction = (fractionPart + "0".repeat(places)).slice(0, places);
  let digits = integerPart + keptFraction;

  const discarded = fractionPart.slice(places);
  let increment = false;

  if (discarded.length > 0) {
    const first = discarded[0];
    if (first > "5") {
      increment = true;
    } else if (first === "5") {
      const rest = discarded.slice(1);
      if (/[^0]/.test(rest)) {
        increment = true;
      } else {
        increment = Number(digits[digits.length - 1]) % 2 === 1;
      }
    }
  }

  if (increment) {
    const chars = digits.split("");
    let i = chars.length - 1;

    while (i >= 0 && chars[i] === "9") {
      chars[i] = "0";
      i--;
