    if (i < 0) {
      chars.unshift("1");
    } else {
      chars[i] = String(Number(chars[i]) + 1);
    }

    digits = chars.join("");
  }

  const integerLength = integerPart.length;
  let resultInteger = digits.slice(0, digits.length - places || digits.length);
  const resultFraction = places > 0 ? digits.slice(-places) : "";

  resultInteger = resultInteger.replace(/^0+(?=\d)/, "");

  const isZero = /^0+$/.test(resultInteger) &&
    (places === 0 || /^0+$/.test(resultFraction));

  if (isZero) {
    return places === 0 ? "0" : "0." + "0".repeat(places);
  }

  return (negative ? "-" : "") +
    resultInteger +
    (places > 0 ? "." + resultFraction : "");
}

