function makeCache(cap) {
  if (cap <= 0) {
    return {
      get: function(key) { return null; },
      set: function(key, value) {},
      keys: function() { return []; }
    };
  }

  const cache = new Map();
  const freqMap = new Map();
  let minFreq = 0;

  function updateFreq(key) {
    const freq = freqMap.get(key);
    freqMap.delete(key);
    const newFreq = freq + 1;
    freqMap.set(key, newFreq);
    if (freq === minFreq && !freqMap.has(key)) {
      minFreq = newFreq;
    }
  }

  function evict() {
    let evictKey = null;
    let minFreqVal = Infinity;
    let lruOrder = Infinity;

    for (const [k, f] of freqMap) {
      if (f < minFreqVal || (f === minFreqVal && cache.get(k).lru < lruOrder)) {
        minFreqVal = f;
        lruOrder = cache.get(k).lru;
        evictKey = k;
      }
    }

    if (evictKey !== null) {
      cache.delete(evictKey);
      freqMap.delete(evictKey);
    }
  }

  return {
    get: function(key) {
      if (!cache.has(key)) return null;
      const entry = cache.get(key);
      updateFreq(key);
      entry.lru = Date.now();
      return entry.value;
    },
    set: function(key, value) {
      if (cache.has(key)) {
        const entry = cache.get(key);
        entry.value = value;
        updateFreq(key);
        entry.lru = Date.now();
      } else {
        if (cache.size >= cap) {
          evict();
        }
        cache.set(key, { value, lru: Date.now() });
        freqMap.set(key, 1);
        minFreq = 1;
      }
    },
    keys: function() {
      return Array.from(cache.keys()).sort();
    }
  };
}

function makeCache(cap) {
  const cache = new Map();
  let clock = 0;

  return {
    get(key) {
      if (cap <= 0) return null;
      const entry = cache.get(key);
      if (!entry) return null;
      entry.uses++;
      entry.recent = ++clock;
      return entry.value;
    },

    set(key, value) {
      if (cap <= 0) return;

      const existing = cache.get(key);
      if (existing) {
        existing.value = value;
        existing.uses++;
        existing.recent = ++clock;
        return;
      }

      if (cache.size >= cap) {
        let leastKey;
        let leastEntry;

        for (const [currentKey, entry] of cache) {
          if (
            !leastEntry ||
            entry.uses < leastEntry.uses ||
            (entry.uses === leastEntry.uses && entry.recent < leastEntry.recent)
          ) {
            leastKey = currentKey;
            leastEntry = entry;
          }
        }

        cache.delete(leastKey);
      }

      cache.set(key, {
        value,
        uses: 1,
        recent: ++clock
      });
    },

    keys() {
      return Array.from(cache.keys()).sort();
    }
  };
}

