function topoOrder(nodes, edges) {
    const adj = new Map();
    const inDeg = new Map();
    for (const n of nodes) {
        adj.set(n, []);
        inDeg.set(n, 0);
    }
    const seen = new Set();
    for (const [u, v] of edges) {
        if (u === v) continue;
        const key = u + ',' + v;
        if (seen.has(key)) continue;
        seen.add(key);
        adj.get(u).push(v);
        inDeg.set(v, inDeg.get(v) + 1);
    }
    const ready = [];
    for (const n of nodes) {
        if (inDeg.get(n) === 0) ready.push(n);
    }
    ready.sort();
    const order = [];
    while (ready.length > 0) {
        const u = ready.shift();
        order.push(u);
        for (const v of adj.get(u)) {
            inDeg.set(v, inDeg.get(v) - 1);
            if (inDeg.get(v) === 0) {
                ready.push(v);
                ready.sort();
            }
        }
    }
    if (order.length < nodes.length) {
        const stuck = [];
        for (const n of nodes) {
            if (order.indexOf(n) === -1) stuck.push(n);
        }
        stuck.sort();
        return { stuck };
    }
    return { order };
}

function topoOrder(nodes, edges) {
  const nodeSet = new Set(nodes);
  const indegree = new Map(nodes.map(node => [node, 0]));
  const adjacency = new Map(nodes.map(node => [node, new Set()]));

  for (const [from, to] of edges) {
    if (!nodeSet.has(from) || !nodeSet.has(to)) continue;
    const targets = adjacency.get(from);
    if (!targets.has(to)) {
      targets.add(to);
      indegree.set(to, indegree.get(to) + 1);
    }
  }

  const compare = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
  const ready = nodes.filter(node => indegree.get(node) === 0).sort(compare);

  const insertReady = node => {
    let low = 0;
    let high = ready.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (compare(ready[mid], node) < 0) low = mid + 1;
      else high = mid;
    }
    ready.splice(low, 0, node);
  };

  const order = [];
  while (ready.length) {
    const node = ready.shift();
    order.push(node);

    for (const next of adjacency.get(node)) {
      const degree = indegree.get(next) - 1;
      indegree.set(next, degree);
      if (degree === 0) insertReady(next);
    }
  }

  if (order.length !== nodes.length) {
    const placed = new Set(order);
    return { stuck: nodes.filter(node => !placed.has(node)).sort(compare) };
  }

  return { order };
}

