    for (let col = 0; col < grid[row].length; col++) {
      if (grid[row][col] !== 1 || visited[row][col]) continue;

      count++;
      const stack = [[row, col]];
      visited[row][col] = true;

      while (stack.length) {
        const [r, c] = stack.pop();
        const neighbors = [
          [r - 1, c],
          [r + 1, c],
          [r, c - 1],
          [r, c + 1]
        ];

        for (const [nr, nc] of neighbors) {
          if (
            nr >= 0 &&
            nr < grid.length &&
            nc >= 0 &&
            nc < grid[nr].length &&
            grid[nr][nc] === 1 &&
            !visited[nr][nc]
          ) {
            visited[nr][nc] = true;
            stack.push([nr, nc]);
          }
        }
      }
    }
  }

  return count;
}

