  function isLeapYear(year) {
    return year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  }

  while (n > 0) {
    if (m === 1 && d === 1 && n >= 146097) {
      const cycles = Math.floor(n / 146097);
      y += cycles * 400;
      n -= cycles * 146097;
      continue;
    }

    const daysInMonth = [31, isLeapYear(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
    const daysUntilNextMonth = daysInMonth - d + 1;

    if (n < daysUntilNextMonth) {
      d += n;
      n = 0;
    } else {
      n -= daysUntilNextMonth;
      d = 1;
      m++;
      if (m === 13) {
        m = 1;
        y++;
      }
    }
  }

  return [y, m, d];
}

