  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      if (grid[i][j] === 1 && !visited[i][j]) {
        count++;
        dfs(i, j);
      }
    }
  }
  return count;
}

function countIslands(grid) {
  if (!grid || grid.length === 0) return 0;

  const visited = grid.map(row => Array(row.length).fill(false));
  let count = 0;
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];

  for (let row = 0; row < grid.length; row++) {
    for (let col = 0; col < grid[row].length; col++) {
      if (grid[row][col] !== 1 || visited[row][col]) continue;

      count++;
      visited[row][col] = true;
      const stack = [[row, col]];

      while (stack.length) {
        const [currentRow, currentCol] = stack.pop();

        for (const [rowOffset, colOffset] of directions) {
          const nextRow = currentRow + rowOffset;
          const nextCol = currentCol + colOffset;

          if (
            nextRow >= 0 &&
            nextRow < grid.length &&
            nextCol >= 0 &&
            nextCol < grid[nextRow].length &&
            grid[nextRow][nextCol] === 1 &&
            !visited[nextRow][nextCol]
          ) {
            visited[nextRow][nextCol] = true;
            stack.push([nextRow, nextCol]);
          }
        }
      }
    }
  }

  return count;
}

function minRooms(meetings) {
  if (!meetings.length) return 0;

  const starts = meetings.map(m => m[0]).sort((a, b) => a - b);
  const ends = meetings.map(m => m[1]).sort((a, b) => a - b);

  let i = 0, j = 0;
  let count = 0;
  let max = 0;

  while (i < meetings.length) {
    if (starts[i] < ends[j]) {
      count++;
      if (count > max) max = count;
      i++;
    } else {
      count--;
      j++;
    }
  }

  return max;
}

function minRooms(meetings) {
  if (meetings.length === 0) return 0;

  const events = [];

  for (const [start, end] of meetings) {
    events.push([start, 1], [end, -1]);
  }

  events.sort((a, b) => a[0] - b[0] || a[1] - b[1]);

  let active = 0;
  let maxRooms = 0;

  for (const [, change] of events) {
    active += change;
    if (active > maxRooms) maxRooms = active;
  }

  return maxRooms;
}

function addDaysToDate(y, m, d, n) {
    function isLeap(year) {
        return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
    }
    function daysInMonth(year, month) {
        var days = [31, isLeap(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
        return days[month - 1];
    }
    d += n;
    while (d > daysInMonth(y, m)) {
        d -= daysInMonth(y, m);
        m++;
        if (m > 12) {
            m = 1;
            y++;
        }
    }
    return [y, m, d];
}

function addDaysToDate(y, m, d, n) {
  const isLeapYear = year =>
    year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);

  const daysInMonth = (year, month) => {
    if (month === 2) return isLeapYear(year) ? 29 : 28;
    return [4, 6, 9, 11].includes(month) ? 30 : 31;
  };

  const daysIn400Years = 146097;
  const cycles = Math.floor(n / daysIn400Years);
  y += cycles * 400;
  n -= cycles * daysIn400Years;

  while (n > 0) {
    const remaining = daysInMonth(y, m) - d;

    if (n <= remaining) {
      d += n;
      n = 0;
    } else {
      n -= remaining + 1;
      d = 1;
      if (m === 12) {
        m = 1;
        y++;
      } else {
        m++;
      }
    }
  }

  return [y, m, d];
}

`deleteUser` does not invalidate the cache. After a successful database deletion, `getUser(id)` can return the stale cached user indefinitely.

```js
async function deleteUser(id) {
  await db.deleteUser(id);
  cache.delete(id);
}
```

The invalidation should occur only after the database deletion succeeds.

**Defect:**  
There is a correctness issue: if a non-`TimeoutError` exception is raised, it is caught by the general `except Exception` block, but no exception is stored, and the function proceeds to retry. If *all* attempts fail with non-Timeout exceptions, `last_error` will be `None`, so `raise last_error` will raise None, which is itself an error (TypeError: exceptions must derive from BaseException).

**Concrete impact:**  
If all retries fail with an exception other than `TimeoutError`, `raise last_error` will fail with a confusing error about trying to raise `None`, hiding the original errors.

**Suggested fix:**  
Store the exception in `last_error` for all failure cases, not just `TimeoutError`:

```python
def fetch_with_retry(url, attempts=3):
    last_error = None
    for _ in range(attempts):
        try:
            return http_get(url)
        except Exception as e:
            last_error = e
    raise last_error
```
Or, if you want to keep the logic of handling `TimeoutError` differently, you could re-raise immediately for other exceptions:

```python
def fetch_with_retry(url, attempts=3):
    last_error = None
    for _ in range(attempts):
        try:
            return http_get(url)
        except TimeoutError as e:
            last_error = e
        except Exception:
            raise  # re-raise unknown exceptions
    raise last_error
```

**Summary:**  
The code has a defect in exception handling; store *all* exceptions in `last_error` to ensure a proper error is raised if all retries fail.

The code works for unique request IDs, but it never removes entries from `timers`. Over time, this causes an unbounded memory leak.

Add cleanup when the request completes, ideally in a `finally` block:

```js
function stopTimer(requestId) {
  const start = timers.get(requestId);
  timers.delete(requestId);
  return start === undefined ? null : Date.now() - start;
}
```

Also ensure `requestId` is unique per concurrent request; calling `startTimer` twice with the same ID overwrites the earlier timer. For accurate elapsed durations, prefer a monotonic clock such as `performance.now()` rather than `Date.now()`, which can change due to system clock adjustments.

The pagination logic is correct for a stable endpoint when `pageSize` is a positive integer. However, it can loop forever for invalid sizes:

- With `pageSize === 0`, `batch.length < 0` is always false and every request uses `offset=0&limit=0`.
- Negative, `NaN`, or infinite values can likewise prevent termination or produce invalid requests.

Validate the argument before looping:

```js
async function fetchAll(endpoint, pageSize) {
  if (!Number.isInteger(pageSize) || pageSize <= 0) {
    throw new RangeError("pageSize must be a positive integer");
  }

  const out = [];
  let page = 0;

  while (true) {
    const batch = await get(
      `${endpoint}?offset=${page * pageSize}&limit=${pageSize}`
    );
    out.push(...batch);
    if (batch.length < pageSize) break;
    page++;
  }

  return out;
}
```

Also, if `endpoint` may already contain query parameters, use `URL`/`URLSearchParams` rather than always appending `?`.

The helper has two correctness defects:

1. **Non-`TimeoutError` exceptions are silently swallowed.**  
   If `http_get` raises, for example, `ConnectionError`, every attempt is ignored and the function eventually executes `raise last_error`, where `last_error` is still `None`. This produces a misleading `TypeError` instead of the original error.

2. **`attempts <= 0` also ends with `raise None`.**  
   This masks the invalid argument with another `TypeError`.

A fix is to validate `attempts`, retry only the intended transient exception, and let other exceptions propagate:

```python
def fetch_with_retry(url, attempts=3):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")

    for attempt in range(attempts):
        try:
            return http_get(url)
        except TimeoutError:
            if attempt == attempts - 1:
                raise  # re-raise the final timeout
```

If all exceptions are intentionally retryable, catch them as `e` and raise the final saved exception rather than using `pass`, though retrying programming errors is generally undesirable.

The function is correct only if every present element is a finite number. Otherwise JavaScript’s coercion and comparison rules can produce incorrect results.

For example:

```js
compareVersions(["10"], ["2"]) // -1, but 10 > 2
```

String comparison is lexicographic. `NaN` is also problematic: comparisons involving it can report `1` in both directions.

Fix by validating numeric inputs (or explicitly converting strings):

```js
function compareVersions(a, b) {
  const len = Math.max(a.length, b.length);

  for (let i = 0; i < len; i++) {
    const x = a[i] === undefined ? 0 : Number(a[i]);
    const y = b[i] === undefined ? 0 : Number(b[i]);

    if (!Number.isFinite(x) || !Number.isFinite(y)) {
      throw new TypeError("Version components must be finite numbers");
    }
    if (x !== y) return x < y ? -1 : 1;
  }
  return 0;
}
```

For arrays guaranteed to contain finite numbers, the original code is correct.

There is a boundary defect if lapse occurs **at** 30 days: the strict `>` comparison returns `false` when the elapsed time is exactly 30 days.

```js
function hasLapsed(lastPaidAt, now) {
  const THIRTY_DAYS = 30 * 24 * 60 * 60 * 1000;
  return now.getTime() - lastPaidAt.getTime() >= THIRTY_DAYS;
}
```

This is correct only if the policy is based on exactly 30 elapsed 24-hour periods. If the subscription is calendar-based (for example, “same date next month”), use calendar-date arithmetic instead; milliseconds can produce different results around daylight-saving transitions or varying month lengths.

